/* S34 (user 2026-10-24, Flow B): the how-it-works screen (ofHowHtml,
   OF_HOW_CARDS, OF_HOW_INLINE, ofToggleHow) and the done screen
   (ofDoneHtml) are deleted — their content lives in the getting-started
   guide and on the Home hero. ONBOARDING_GUIDE_URL went with them (its
   only in-flow references were those two screens). */
/* Returns the markup for a flow screen by name (defaults to the setup choice). */
function ofScreenHtml(name){
  switch(name){
    case 'choice':return ofChoiceHtml();
    case 'options':return ofOptionsHtml();
    case 'import':return ofImportHtml();
    case 'signin':return ofSigninHtml();
    default:return ofChoiceHtml();
  }
}
/* ===== flow controller ===== */
/* Starts the onboarding flow (resets state, builds the overlay, opens on
   the setup choice; the post-sign-up entry omits the sign-in step). */
function startOnboardingFlow(opts){
  ofResetState();
  /* B9d (2026-10-28): resume — restore the stored step's answers
     (only the flow's own keys; a marker is local data, never trusted
     beyond its shape) and land on the stored screen at the end. A
     fresh start clears any stale marker the new flow replaces. */
  const resume=(opts&&opts.resume&&OF_SCREENS.includes(opts.resume.screen))?opts.resume:null;
  if(resume){
    const saved=(resume.state&&typeof resume.state==='object')?resume.state:{};
    for(const k of Object.keys(ofState))if(k in saved)ofState[k]=saved[k];
    ofState.screen=resume.screen;
  }else{
    ofClearProgress();
  }
  /* #506 follow-up (user 2026-09-16): opts.signedIn marks the post-sign-up
     entry (maybeStartPostSignupOnboarding) — the account already exists,
     so the flow omits its sign-in step (import finishes instead). */
  if(opts&&opts.signedIn)ofState.signedIn=true;
  /* FORK v1.991.73 (R13, fix-list item 25F): an explicit launch return —
     the QA replay passes {returnTo:'settings'} so finishing (or
     skipping) lands back on Settings, the surface that launched it.
     The routeHash capture below cannot be trusted for this: Settings
     reached without a history push leaves a stale hash behind, and
     the flow used to land on Home instead. */
  if(opts&&opts.returnTo)ofState.returnTo=String(opts.returnTo);
  /* #506 follow-up: remember an ordinary deep-link hash so finishOnboarding
     can route back to it. Share links never reach this flow.
     B9d: a resume keeps the hash captured when the flow first started. */
  if(!resume){
    try{
      ofState.routeHash=decodeURIComponent(String(location.hash||'').replace(/^#/,'')).trim();
    }catch(_){ofState.routeHash='';}
  }
  /* #511: on replay (QA "Replay onboarding") the opt-in checkbox reflects
     the live prefs instead of always resetting to checked — the box is a
     master switch over all three prefs, so it reads checked only when all
     three are currently on. Fresh profiles have no prefs (default ON) →
     checked. B9d: a resume keeps the answer the user already gave. */
  if(!resume){
    try{
      if(typeof subscriptionOn==='function'){
        ofState.marketing=subscriptionOn('appUpdates')&&subscriptionOn('marketing')&&subscriptionOn('tips');
      }
    }catch(_){}
  }
  let flow=null;
  try{flow=document.getElementById('onboardingFlow');}catch(_){}
  if(!flow){
    try{
      flow=document.createElement('div');
      flow.id='onboardingFlow';
      flow.setAttribute('role','dialog');
      flow.setAttribute('aria-label','Welcome to Kohlrabi');
      flow.innerHTML='<div class="of-phone"><div id="ofBody"></div></div>';
      document.body.appendChild(flow);
    }catch(_){return;}
  }
  try{
    flow.hidden=false;
    document.body.classList.add('of-active');
  }catch(_){}
  ofGo(resume?resume.screen:'choice');
}
/* Shows a flow screen: renders its markup, re-wires handlers, resets scroll. */
function ofGo(name){
  ofState.screen=name;
  /* B9d (2026-10-28): every transition re-stamps the resume marker. */
  ofWriteProgress();
  let body=null;
  try{body=document.getElementById('ofBody');}catch(_){}
  if(body){body.innerHTML=ofScreenHtml(name);body.scrollTop=0;}
  ofWire();
  try{window.scrollTo(0,0);}catch(_){}
}
/* The code step's back chevron returns to the email step rather than leaving
   sign-in (pure so tests can pin it). */
function ofResolveBack(target){
  if(target==='signin-email'){ofState.signinStep='email';return 'signin';}
  return target;
}
/* One delegated click handler per screen render (replaced on every ofGo, so
   handlers never double-bind). */
/* One delegated click handler per screen render (replaced on every ofGo, so handlers never double-bind), plus per-screen wiring. */
function ofWire(){
  let body=null;
  try{body=document.getElementById('ofBody');}catch(_){}
  if(!body)return;
  body.onclick=(e)=>{
    const t=e&&e.target;
    if(!t||!t.closest)return;
    const goEl=t.closest('[data-of-go]');
    if(goEl){
      /* #506 follow-up (user 2026-09-16): the post-sign-up entry omits the
         sign-in step, so any navigation to it jumps to setup choice
         instead. (S34: no in-flow control navigates to sign-in anymore —
         import advances there — this stays as a guard.) */
      let dest=goEl.getAttribute('data-of-go');
      if(dest==='signin'&&ofState.signedIn)dest='choice';
      ofGo(dest);return;
    }
    const backEl=t.closest('[data-of-back]');
    if(backEl){ofGo(ofResolveBack(backEl.getAttribute('data-of-back')));return;}
    const pick=t.closest('[data-of-segval],[data-of-pillval]');
    if(pick){ofPick(pick);return;}
    const sw=t.closest('[data-of-switch]');
    if(sw){ofToggleSwitch(sw);return;}
    const setupEl=t.closest('[data-of-setup]');
    if(setupEl){
      ofState.setup=setupEl.getAttribute('data-of-setup')==='custom'?'custom':'defaults';
      /* Update the ring in place — re-rendering the whole screen here caused
         a visible flash/animation when toggling between the two cards. */
      const cards=setupEl.closest('.of-cards');
      if(cards)cards.querySelectorAll('[data-of-setup]').forEach(c=>{
        const sel=c===setupEl;
        c.classList.toggle('of-card-sel',sel);
        c.setAttribute('aria-pressed',String(sel));
      });
      return;
    }
    const skipEl=t.closest('[data-of-skip]');
    if(skipEl){
      /* #506 follow-up: skipping from the Options screen keeps the custom
         settings already picked (same apply step as Continue). */
      if(ofState.screen==='options')ofApplyOptions();
      /* Audit UX batch (user ruling 2026-10-28): the sign-in step's
         only skip is "No thanks" — a decline. Mark it so the Home
         hero suppresses its Sign in row for the session. */
      if(ofState.screen==='signin')markHeroSignInDeclined();
      finishOnboarding();return;
    }
  };
  const on=(id,fn)=>{const el=body.querySelector('#'+id);if(el)el.addEventListener('click',fn);};
  if(ofState.screen==='signin')ofWireSignin(body);
  /* #511: the marketing opt-in checkbox is a master switch — all or
     nothing (user 2026-09-16): it sets all three subscription prefs at
     once. Unchecked opts out of everything, including app updates and
     tips; checked opts into all three. */
  const mktBox=body.querySelector('#ofMarketingOptIn');
  if(mktBox)mktBox.addEventListener('change',()=>ofApplyMarketingOptIn(mktBox.checked));
  on('ofChoiceNext',()=>{
    if(ofState.setup==='custom'){ofState.cameFromOptions=true;ofGo('options');}
    else{ofState.cameFromOptions=false;ofApplyBranchSettings();ofGo('import');}
  });
  on('ofOptionsContinue',()=>{ofApplyOptions();ofGo('import');});
  /* #506 follow-up (user 2026-09-16): the Import button opens the real file
     picker immediately — the standalone import overlay paints above the flow
     (its z-index exceeds the flow's) and returns to the import screen when
     closed. No intent handoff needed anymore. */
  on('ofImportNow',()=>{
    ofState.imp='done';
    try{if(typeof openCsvImport==='function')openCsvImport();}catch(_){}
  });
  /* S34 (user 2026-10-24, Flow B): import advances to sign-in, the last
     step — or finishes outright on the post-sign-up entry, which omits
     the sign-in step. */
  on('ofImportSkip',()=>{ofState.imp='skipped';if(ofState.signedIn)finishOnboarding();else ofGo('signin');});
}
/* Shared Options-screen apply step (Continue and "Skip to the app" both run
   it so a skip from Options keeps the picked settings). */
function ofApplyOptions(){
  ofState.cameFromOptions=(ofState.setup==='custom');
  ofApplyBranchSettings();
}
/* #511: the marketing opt-in checkbox is a master switch — all or nothing
   (user 2026-09-16, x3). Checked opts all three prefs in; unchecked opts
   all three out, including app updates and tips. Afterwards each toggles
   independently in Settings → Data → Privacy. */
function ofApplyMarketingOptIn(checked){
  ofState.marketing=!!checked;
  try{if(typeof setAllSubscriptions==='function')setAllSubscriptions(!!checked);}catch(_){}
}
/* Applies a segmented/pill choice: updates flow state and the group's pressed styles in place. */
function ofPick(btn){
  const name=btn.getAttribute('data-of-name');
  const val=btn.getAttribute('data-of-segval')||btn.getAttribute('data-of-pillval');
  if(!name||val==null)return;
  ofState[name]=val;
  const isSeg=btn.hasAttribute('data-of-segval');
  const group=btn.closest('[data-of-seg],[data-of-pills]');
  const selClass=isSeg?'of-seg-sel':'of-sel';
  if(group)group.querySelectorAll('button').forEach(b=>{b.classList.remove('of-seg-sel','of-sel');b.setAttribute('aria-pressed','false');});
  btn.classList.add(selClass);
  btn.setAttribute('aria-pressed','true');
}
/* iOS switch pattern (matches the mockup; not the app's press-pill switch —
   the flow is a self-contained full-screen takeover). */
function ofToggleSwitch(sw){
  const on=sw.classList.toggle('of-on');
  sw.setAttribute('aria-checked',String(on));
  ofState.prog=on?'on':'off';
}
/* ===== sign-in (email OTP, optional — reuses sync-auth's parameterized
   actions with the flow's own status writer) ===== */
/* Writes a message to the sign-in step's status line. */
function ofSetStatus(msg,isErr){
  let el=null;
  try{el=document.getElementById('ofSigninStatus');}catch(_){}
  if(!el)return;
  el.textContent=msg||'';
  el.classList.toggle('of-error',!!isErr);
}
/* True when the sync-auth module's sign-in actions are available. */
function ofSyncAvailable(){
  return (typeof Sync!=='undefined')&&!!Sync
    &&typeof Sync.requestSignInCode==='function'
    &&typeof Sync.confirmSignInCode==='function';
}
/* Wires the sign-in screen: send/resend/verify buttons, the digit-box code input, and Enter-to-send. */
function ofWireSignin(body){
  const on=(id,fn)=>{const el=body.querySelector('#'+id);if(el)el.addEventListener('click',fn);};
  on('ofSendCode',()=>ofSendCode(false));
  on('ofResendCode',()=>ofSendCode(true));
  on('ofVerifyCode',ofVerifyCode);
  const codeInput=body.querySelector('#ofCodeInput');
  const digitBoxes=Array.from(body.querySelectorAll('.of-codebox'));
  if(codeInput&&digitBoxes.length){
    /* One input drives the visual boxes: digits-only, capped at 8; the
       first empty box gets the focus ring. Paste and iOS autofill just work. */
    const renderCode=()=>{
      const v=(codeInput.value||'').replace(/\D/g,'').slice(0,8);
      if(codeInput.value!==v)codeInput.value=v;
      let nextMarked=false;
      digitBoxes.forEach((b,i)=>{
        const ch=v[i]||'';
        if(b.textContent!==ch)b.textContent=ch;
        b.classList.toggle('of-filled',!!ch);
        const isNext=!ch&&!nextMarked;
        b.classList.toggle('of-next',isNext);
        if(isNext)nextMarked=true;
      });
    };
    codeInput.addEventListener('input',renderCode);
    renderCode();
  }
  const email=body.querySelector('#ofEmail');
  if(email)email.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();ofSendCode(false);}});
}
/* Requests an 8-digit sign-in code for the typed email and advances to the code step. */
async function ofSendCode(isResend){
  let input=null;
  try{input=document.getElementById('ofEmail');}catch(_){}
  /* Persona QA 2026-09-16: the typed address is only the account email once
     a code was actually sent for it — stashing it before validation let an
     invalid address ("not-an-email") show up as the Done screen's Account. */
  const typed=((input&&input.value)||ofState.email||'').trim();
  if(!ofSyncAvailable()){ofSetStatus('Sign-in is unavailable right now.',true);return;}
  let ok=false;
  try{ok=await Sync.requestSignInCode({email:typed,setStatus:ofSetStatus});}catch(_){ok=false;}
  if(ok){
    ofState.email=typed;
    ofState.signinStep='code';
    ofGo('signin');
    ofSetStatus(isResend?'Code re-sent. Check your email.':'Code sent. Check your email.');
    let first=null;
    try{first=document.querySelector('#ofBody #ofCodeInput');}catch(_){}
    if(first&&first.focus)try{first.focus({preventScroll:true});}catch(_){try{first.focus();}catch(_){}}
  }
}
/* Verifies the 8-digit code; on success the flow finishes, for every
   account. S34 (user 2026-10-24, Flow B): sign-in is the LAST step, so
   there is nothing after it to skip to — the 2026-09-22 existing-account
   early finish and its ofIsExistingAccount created_at heuristic are
   deleted. A returning account's data syncs down on Home as usual; a
   brand-new account keeps the settings it picked earlier in the flow
   (nothing is reset here, and no remote blob exists to overwrite them). */
async function ofVerifyCode(){
  let input=null;
  try{input=document.getElementById('ofCodeInput');}catch(_){}
  const token=((input&&input.value)||'').replace(/\D/g,'').slice(0,8);
  if(!ofSyncAvailable()){ofSetStatus('Sign-in is unavailable right now.',true);return;}
  if(token.length!==8){ofSetStatus('Enter the 8-digit code from your email.',true);return;}
  let ok=false;
  try{ok=await Sync.confirmSignInCode({email:ofState.email,token:token,setStatus:ofSetStatus});}catch(_){ok=false;}
  if(ok){
    ofState.emailVerified=true;
    ofState.signinStep='email';
    finishOnboarding();
  }
}
/* ===== completion ===== */
/* #506 follow-up (user 2026-09-16): route back to an ordinary deep link after
   the flow completes — ordinary hashes no longer suppress onboarding, so the
   destination must survive the flow. Share links never reach this flow.
   Returns true when a deep link was consumed. */
function ofRouteDeepLink(){
  const id=ofState.routeHash||'';
  if(!id)return false;
  try{
    if(id==='library'){if(typeof showLibrary==='function')showLibrary(false);return true;}
    if(id==='workout'){if(typeof showWorkouts==='function')showWorkouts(false);return true;}
    if(id==='program'){
      try{if(typeof state!=='undefined'&&state&&typeof programSetupOpen==='function'){
        if(!state.activeProgram)programSetupOpen();
      }}catch(_){}
      if(typeof showProgram==='function')showProgram(false);
      try{if(typeof maybeOfferNewProgramForDeepLink==='function')maybeOfferNewProgramForDeepLink();}catch(_){}
      return true;
    }
    if(id==='stats'){if(typeof showStats==='function')showStats(false);return true;}
    if(id==='settings'){if(typeof showSettings==='function')showSettings(false);return true;}
    if(/^[a-zA-Z0-9_-]{3,}$/.test(id)&&typeof openExercise==='function'){
      try{openExercise(id,false);return true;}catch(_){return false;}
    }
  }catch(_){}
  return false;
}
/* #506 follow-up (user 2026-09-16): first-time sign-up entry point, called
   from handleAuthChange. The boot gate only runs at load, so a sign-up that
   happens later (Settings → account, or the in-flow sign-in) needs its own
   trigger. Fires only for a genuinely new account on a data-free profile
   whose flow never completed; the in-flow sign-in already continues the flow
   (body is of-active), so this skips when the flow is already up. Returns
   true when the flow was started. */
async function maybeStartPostSignupOnboarding(isFreshAccount){
  if(!isFreshAccount)return false;
  try{if(typeof startOnboardingFlow!=='function')return false;}catch(_){return false;}
  let done=false,showing=false,hasData=false;
  try{done=localStorage.getItem(ONBOARDING_DONE_KEY)==='1';}catch(_){}
  try{showing=document.body.classList.contains('of-active');}catch(_){showing=true;}
  try{
    const pk=typeof PERSIST_KEY!=='undefined'?PERSIST_KEY:null;
    const bk=typeof LS_BACKUP_KEY!=='undefined'?LS_BACKUP_KEY:null;
    /* DSA-05 (v1.997.39): the same wipe-plant filter ofGateInputs applies
       (#537) — a wipe stamps an empty plant under PERSIST_KEY, and a wiped
       profile that creates a fresh account must not read as having data. */
    const pkRaw=pk?localStorage.getItem(pk):null;
    if(pkRaw!=null&&!isWipePlantRaw(pkRaw))hasData=true;
    else{
      const bkRaw=bk?localStorage.getItem(bk):null;
      if(bkRaw!=null&&!isWipePlantRaw(bkRaw))hasData=true;
    }
  }catch(_){}
  if(done||showing||hasData)return false;
  try{startOnboardingFlow({signedIn:true});}catch(_){return false;}
  return true;
}
/* Completes onboarding: stamps the done flag, hides the flow, and routes to the deep link or Home. */
function finishOnboarding(){
  try{localStorage.setItem(ONBOARDING_DONE_KEY,'1');}catch(_){}
  /* B9d (2026-10-28): finishing (or explicitly exiting — every exit
     funnels through here) clears the in-progress marker. */
  ofClearProgress();
  let flow=null;
  try{
    flow=document.getElementById('onboardingFlow');
    if(flow)flow.hidden=true;
    document.body.classList.remove('of-active');
  }catch(_){}
  /* #506 follow-up (user 2026-09-16): back to the pending deep link when one
     was captured; otherwise land on Home — the fresh account shows the
     "No workouts yet" empty-state hero. */
  let routed=false;
  /* FORK v1.991.73 (R13, item 25F): an explicit launch return outranks
     the deep-link capture — a replay finishes back where it started. */
  if(ofState.returnTo==='settings'){
    try{if(typeof showSettings==='function'){showSettings(false);routed=true;}}catch(_){routed=false;}
  }
  if(!routed){try{routed=ofRouteDeepLink();}catch(_){routed=false;}}
  if(!routed){
    try{if(typeof showDashboard==='function')showDashboard(false);}catch(_){}
  }
}
/* #537 (2026-09-17): a wipe (delete-all / sign-out / delete-account) returns
   the profile to fresh, so the first-run gate must reset with it — otherwise
   the onboarding flow never resurfaces on the wiped profile. Called from
   wipeLocalUserData() (persistence.js, guarded); kept here with the key. */
function clearOnboardingDone(){
  try{localStorage.removeItem(ONBOARDING_DONE_KEY);}catch(_){}
  /* B9d (2026-10-28): a wipe resets the resume marker with the flag. */
  ofClearProgress();
}
/* ===== QA-only replay trigger (#506, user 2026-09-16) ===== */
/* "Replay onboarding" button for testing the first-run flow on QA builds.
   Shown ONLY on non-prod hosts (beta.kohlrabi.us, *.pages.dev, localhost,
   etc.) — never on kohlrabi.us / www.kohlrabi.us / app.cruciferousgreens.com.
   Fail-closed: an undeterminable hostname hides the button. */
function wireOnboardingReplay(){
  let btn=null,row=null;
  try{
    btn=document.getElementById('replayOnboardingButton');
    row=document.getElementById('qaOnboardingRow');
  }catch(_){return;}
  if(!btn||!row)return;
  let prod=true;
  try{
    const h=String(location.hostname||'').toLowerCase();
    prod=(h===''||h==='kohlrabi.us'||h==='www.kohlrabi.us'||h==='app.cruciferousgreens.com');
  }catch(_){prod=true;}
  if(prod)return;
  try{row.hidden=false;}catch(_){}
  btn.addEventListener('click',()=>{
    clearOnboardingDone();
    /* FORK v1.991.73 (R13, item 25F): the replay is launched FROM
       Settings, so it returns to Settings on finish or skip. */
    startOnboardingFlow({returnTo:'settings'});
  });
}
